document.querySelectorAll(".specify-sidebar").forEach(l=>{l.querySelectorAll(".specify-node-children").forEach(e=>{e.querySelectorAll(".specify-node-link.specify-node-link--active").length>0||e.classList.add("hidden")}),l.querySelectorAll(".specify-node-label").forEach(e=>{const n=e.parentElement.querySelectorAll(".specify-node-children");e.addEventListener("click",()=>{n.forEach(r=>{r.classList.toggle("hidden")})})})});
